{* Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/feature-metric-cards.json
    Four figures of FeatureSplit as small cards in two columns: a glyph tile, the value with its hint and the label.
    Props (p): stats. *}
{var $v_stats = ($p['stats'] ?? null)}
{capture $c_7}
  {foreach ui_l($v_stats) as $v_s}
    {var $v_i = $iterator->counter0}
    {if ui_t(ui_lt($v_i, 4))}
      {capture $c_6}
        {capture $c_1}
          {=ui_include('ui/lucide-icon/lucide-icon.latte', ['p' => ['Name' => ui_s(ui_get($v_s, ['icon'])), 'Size' => 20]])|noescape}
        {/capture}
        {=ui_include('ui/inline/inline.latte', ['p' => ['Class' => 'flex size-10 shrink-0 items-center justify-center rounded bg-muted text-foreground'], 'children' => $c_1])|noescape}
        {capture $c_5}
          {capture $c_2}
            {=ui_text(ui_get($v_s, ['value']))}
          {/capture}
          {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'lg', 'Weight' => 'bold'], 'children' => $c_2])|noescape}
          {capture $c_3}
            {=ui_text(ui_get($v_s, ['label']))}
          {/capture}
          {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'xs', 'Class' => 'text-muted-foreground'], 'children' => $c_3])|noescape}
          {capture $c_4}
            {=ui_text(ui_get($v_s, ['hint']))}
          {/capture}
          {=ui_include('ui/text/text.latte', ['p' => ['Size' => 'xs', 'Class' => 'text-muted-foreground'], 'children' => $c_4])|noescape}
        {/capture}
        {=ui_include('ui/stack/stack.latte', ['p' => ['Gap' => '0', 'Class' => 'min-w-0'], 'children' => $c_5])|noescape}
      {/capture}
      {=ui_include('ui/group/group.latte', ['p' => ['Gap' => '4', 'Align' => 'center', 'Class' => 'rounded bg-card inset-ring inset-ring-border p-4', 'Attrs' => ui_attrs(['data-testid', 'feature-stat'])], 'children' => $c_6])|noescape}
    {/if}
  {/foreach}
{/capture}
{=ui_include('ui/box/box.latte', ['p' => ['Class' => 'grid grid-cols-1 gap-4 sm:grid-cols-2'], 'children' => $c_7])|noescape}
